def make_socks_proxy_opts(socks_proxy):
    url_components = urllib.parse.urlparse(socks_proxy)
    if url_components.scheme.lower() == 'socks5':
        socks_type = ProxyType.SOCKS5
        rdns = False
    elif url_components.scheme.lower() == 'socks5h':
        socks_type = ProxyType.SOCKS5
        rdns = True
    elif url_components.scheme.lower() == 'socks4':
        socks_type = ProxyType.SOCKS4
        rdns = False
    elif url_components.scheme.lower() == 'socks4a':
        socks_type = ProxyType.SOCKS4A
        rdns = True
    else:
        raise ValueError(f'Unknown SOCKS proxy version: {url_components.scheme.lower()}')

    def unquote_if_non_empty(s):
        if not s:
            return s
        return urllib.parse.unquote_plus(s)
    return {
        'proxytype': socks_type,
        'addr': url_components.hostname,
        'port': url_components.port or 1080,
        'rdns': rdns,

from yt_dlp.networking._helper import make_socks_proxy_opts


def _probe(label, value):
    try:
        result = make_socks_proxy_opts(value)
        return {
            "label": label,
            "kind": "output",
            "value_repr": repr(result),
        }
    except Exception as e:
        return {
            "label": label,
            "kind": "exception",
            "exception_type": type(e).__name__,
            "exception_message": str(e),
        }


class TestMakeSocksProxyOptsIncompatibleTypesQA:
    def test_make_socks_proxy_opts_incompatible_types_case(self):
        snapshots = [
            _probe("bytes_url", b"socks5://host:1080"),
            _probe("int_value", 12345),
            _probe("none_value", None),
        ]

        # Shape-only assertions; do not reveal kinds, types, or messages.
        assert isinstance(snapshots, list)
        assert len(snapshots) == 3
